-- Schema for database: schemabench_0239
CREATE TABLE students (
  student_id INT(11) NOT NULL AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) NOT NULL,
  major VARCHAR(255) NOT NULL,
  PRIMARY KEY (student_id)
);

CREATE TABLE courses (
  course_id INT(11) NOT NULL AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  department VARCHAR(255) NOT NULL,
  credit INT(11) NOT NULL,
  PRIMARY KEY (course_id)
);

CREATE TABLE enrollments (
  enrollment_id INT(11) NOT NULL AUTO_INCREMENT,
  student_id INT(11) NOT NULL,
  course_id INT(11) NOT NULL,
  term VARCHAR(255) NOT NULL,
  PRIMARY KEY (enrollment_id),
  FOREIGN KEY (student_id) REFERENCES students (student_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (course_id) REFERENCES courses (course_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE instructors (
  instructor_id INT(11) NOT NULL AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  department VARCHAR(255) NOT NULL,
  PRIMARY KEY (instructor_id)
);

CREATE TABLE departments (
  department_id INT(11) NOT NULL AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  PRIMARY KEY (department_id)
);

CREATE TABLE department_chairs (
  department_id INT(11) NOT NULL,
  instructor_id INT(11) NOT NULL,
  PRIMARY KEY (department_id, instructor_id),
  FOREIGN KEY (department_id) REFERENCES departments (department_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (instructor_id) REFERENCES instructors (instructor_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE user_roles (
  user_id INT(11) NOT NULL,
  role VARCHAR(255) NOT NULL,
  PRIMARY KEY (user_id, role)
);

CREATE TABLE user_permissions (
  user_id INT(11) NOT NULL,
  permission VARCHAR(255) NOT NULL,
  PRIMARY KEY (user_id, permission)
);

CREATE TABLE user_sessions (
  session_id INT(11) NOT NULL AUTO_INCREMENT,
  user_id INT(11) NOT NULL,
  PRIMARY KEY (session_id),
  FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE user_activity (
  user_id INT(11) NOT NULL,
  activity_id INT(11) NOT NULL,
  PRIMARY KEY (user_id, activity_id),
  FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (activity_id) REFERENCES activities (activity_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE activities (
  activity_id INT(11) NOT NULL AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  PRIMARY KEY (activity_id)
);

CREATE TABLE activity_logs (
  activity_log_id INT(11) NOT NULL AUTO_INCREMENT,
  user_id INT(11) NOT NULL,
  activity_id INT(11) NOT NULL,
  timestamp DATETIME NOT NULL,
  PRIMARY KEY (activity_log_id),
  FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (activity_id) REFERENCES activities (activity_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE user_preferences (
  user_id INT(11) NOT NULL,
  preference VARCHAR(255) NOT NULL,
  PRIMARY KEY (user_id, preference)
);

CREATE TABLE user_settings (
  user_id INT(11) NOT NULL,
  setting VARCHAR(255) NOT NULL,
  PRIMARY KEY (user_id, setting)
);

CREATE TABLE user_notifications (
  user_id INT(11) NOT NULL,
  notification_id INT(11) NOT NULL,
  PRIMARY KEY (user_id, notification_id),
  FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE ON UPDATE CASCADE,
  FOREIGN KEY (notification_id) REFERENCES notifications (notification_id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE notifications (
  notification_id INT(11) NOT NULL AUTO_INCREMENT,
  message VARCHAR(255) NOT NULL,
  PRIMARY KEY (notification_id)
);

CREATE TABLE user_feedback (
  user_id INT(11) NOT NULL,
  feedback VARCHAR(255) NOT NULL,
